def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    if board[row][col] == 'c':
        board[row][col] = 'W'
        for i in range(row+1, 64):
            if board[i][col] == 'S':
                board[i][col] = 'W'
    else:
        board[row][col] = 'S'
        for i in range(row, -1, -1):
            if board[i][col] == 'W':
                board[i][col] = 'S'

    next_board = [list(row) for row in board]
    for r in range(64):
        for c in range(64):
            if next_board[r][c] == 'W':
                next_board[r][c] = 'W' if r < 63 and next_board[r+1][c] == 'W' else 'W'
            elif next_board[r][c] == 'S':
                next_board[r][c] = 'S' if r > 0 and next_board[r-1][c] == 'S' else 'S'

    return [''.join(row) for row in next_board]
